{"path": "csvfix/impl.py", "content": "def parse(line):
    """把一行 CSV 拆成 3 个字段：逐个裁剪空白，列数不是 3 则返回 None。"""
    fields = [f.strip() for f in line.split(",")]
    if len(fields) != 3:
        return None
    return fields


